import type { ServiceId } from "./services";

export type CaseStudy = {
  slug: string;
  title: string;
  /**
   * "demonstration" projects are illustrative scenarios, not client work.
   * They are always labelled as such. Switch to "client" only for real,
   * approved engagements, and only then add verified `results`.
   */
  kind: "demonstration" | "client";
  service: ServiceId;
  sector: string;
  summary: string;
  challenge: string[];
  requirements: string[];
  approach: { title: string; body: string }[];
  technologies: string[];
  implementation: { phase: string; body: string }[];
  /** What the engagement would track. Not results. */
  measures: string[];
  /** Verified, client-approved outcomes only. Leave empty for demonstrations. */
  results: { value: string; label: string }[];
};

